const incoming = $json.body ?? $json;
const jobId = incoming.jobId || ('cf-' + Date.now());
const product = incoming.product || incoming.productName || {};
const productName = typeof product === 'string'
  ? product
  : (product.name || incoming.productName || 'Товар');

const rawVariants = Number(incoming.variants || incoming.count || 1);
const variants = Math.max(1, Math.min(3, Number.isFinite(rawVariants) ? rawVariants : 1));

const job = {
  jobId,
  receivedAt: new Date().toISOString(),
  action: incoming.action || 'create_content',
  productId: incoming.productId || product.id || null,
  productName,
  productDescription: incoming.productDescription || product.description || '',
  productFacts: incoming.productFacts || product.facts || incoming.specs || product.specs || {},
  platforms: incoming.platforms || ['TikTok','Reels','Shorts'],
  variants,
  durationSeconds: Math.max(10, Math.min(60, Number(incoming.durationSeconds || 20))),
  language: incoming.language || 'ru',
  media: incoming.media || product.media || [],
  constraints: {
    vertical: '9:16',
    preserveRealProduct: true,
    noInventedSpecs: true,
    mobileReadable: true,
    premiumRealism: true
  },
  payload: incoming
};

return [{
  json: {
    ...job,
    sourceFileName: jobId + ' — ' + productName.replace(/[\\/:*?"<>|]/g,'_') + '.json',
    sourceFileContent: JSON.stringify(job, null, 2)
  }
}];

const response = $json;
const job = $('Подготовить задачу').item.json;

let raw = response.output_text;
if (!raw && Array.isArray(response.output)) {
  for (const item of response.output) {
    if (!Array.isArray(item.content)) continue;
    const block = item.content.find(x => x.type === 'output_text' && typeof x.text === 'string');
    if (block?.text) { raw = block.text; break; }
  }
}

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('OpenAI не вернул текст плана');
}

raw = raw.trim().replace(/^\`\`\`(?:json)?\s*/i,'').replace(/\s*\`\`\`$/,'');
let plan;
try {
  plan = JSON.parse(raw);
} catch (e) {
  throw new Error('Ответ OpenAI не является валидным JSON: ' + e.message);
}

const variants = Array.isArray(plan.variants) ? plan.variants : [];
if (!variants.length) throw new Error('В AI-плане нет вариантов');
if (variants.length > job.variants) plan.variants = variants.slice(0, job.variants);

const allowedMedia = new Set((job.media || []).map(x => typeof x === 'string' ? x : (x.url || x.id || x.path)).filter(Boolean));

for (const v of plan.variants || []) {
  for (const s of v.scenes || []) {
    if (Array.isArray(s.referenceMedia)) {
      s.referenceMedia = s.referenceMedia.filter(x => allowedMedia.has(x));
    }
  }
}

plan.jobId = job.jobId;
plan.productName = job.productName;
plan.generatedAt = new Date().toISOString();
plan.status = 'storyboard_ready';

const safeName = String(job.productName || 'Товар').replace(/[\\/:*?"<>|]/g,'_');
return [{
  json: {
    jobId: job.jobId,
    productName: job.productName,
    plan,
    planFileName: job.jobId + ' — ' + safeName + ' — storyboard.json',
    planFileContent: JSON.stringify(plan, null, 2)
  }
}];
